CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE admin_account(id smallint PRIMARY KEY DEFAULT 1 CHECK(id=1),username text NOT NULL UNIQUE CHECK(username~'^[a-z0-9._-]{3,64}$'),password_hash text NOT NULL,force_password_change boolean NOT NULL DEFAULT true,active boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin_sessions(id bigserial PRIMARY KEY,session_hash text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),last_used_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE INDEX admin_sessions_lookup ON admin_sessions(session_hash) WHERE revoked_at IS NULL;
CREATE TABLE job_roles(id bigserial PRIMARY KEY,slug text NOT NULL UNIQUE,title text NOT NULL,description text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true,archived_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE role_rule_versions(id bigserial PRIMARY KEY,job_role_id bigint NOT NULL REFERENCES job_roles(id),seniority text,status text NOT NULL CHECK(status IN('draft','published','archived')),version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_role_id,seniority,version));
CREATE TABLE role_rules(id bigserial PRIMARY KEY,version_id bigint NOT NULL REFERENCES role_rule_versions(id) ON DELETE CASCADE,canonical_term text NOT NULL,required boolean NOT NULL,weight numeric(6,2) NOT NULL CHECK(weight>0),category text NOT NULL,expected_section text,recommendation_id text);
CREATE TABLE rule_aliases(id bigserial PRIMARY KEY,rule_id bigint NOT NULL REFERENCES role_rules(id) ON DELETE CASCADE,alias text NOT NULL,UNIQUE(rule_id,alias));
CREATE TABLE rule_exclusions(id bigserial PRIMARY KEY,rule_id bigint NOT NULL REFERENCES role_rules(id) ON DELETE CASCADE,phrase text NOT NULL,UNIQUE(rule_id,phrase));
CREATE TABLE section_requirements(id bigserial PRIMARY KEY,version_id bigint NOT NULL REFERENCES role_rule_versions(id) ON DELETE CASCADE,section_name text NOT NULL,guidance text NOT NULL DEFAULT '');
CREATE TABLE recommendation_templates(id text PRIMARY KEY,copy text NOT NULL,active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1);
CREATE TABLE catalog_snapshots(version text PRIMARY KEY,snapshot jsonb NOT NULL,published_at timestamptz NOT NULL,created_by smallint REFERENCES admin_account(id));
CREATE TABLE role_requests(id bigserial PRIMARY KEY,role_title text NOT NULL CHECK(length(role_title)<=100),seniority text,industry text CHECK(length(industry)<=200),desired_skills text CHECK(length(desired_skills)<=500),reply_email text CHECK(length(reply_email)<=254),status text NOT NULL DEFAULT 'new' CHECK(status IN('new','reviewing','planned','added','rejected','duplicate')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE aggregate_events(id bigserial PRIMARY KEY,event_name text NOT NULL CHECK(event_name IN('scan_started','scan_completed','role_request_submitted')),role_slug text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id bigserial PRIMARY KEY,action text NOT NULL,summary jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE site_settings(id smallint PRIMARY KEY DEFAULT 1 CHECK(id=1),donation_url text,ads_enabled boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO site_settings(id) VALUES(1) ON CONFLICT DO NOTHING;
ALTER TABLE admin_account ENABLE ROW LEVEL SECURITY;ALTER TABLE admin_sessions ENABLE ROW LEVEL SECURITY;ALTER TABLE job_roles ENABLE ROW LEVEL SECURITY;ALTER TABLE role_rule_versions ENABLE ROW LEVEL SECURITY;ALTER TABLE role_rules ENABLE ROW LEVEL SECURITY;ALTER TABLE rule_aliases ENABLE ROW LEVEL SECURITY;ALTER TABLE rule_exclusions ENABLE ROW LEVEL SECURITY;ALTER TABLE section_requirements ENABLE ROW LEVEL SECURITY;ALTER TABLE recommendation_templates ENABLE ROW LEVEL SECURITY;ALTER TABLE catalog_snapshots ENABLE ROW LEVEL SECURITY;ALTER TABLE role_requests ENABLE ROW LEVEL SECURITY;ALTER TABLE aggregate_events ENABLE ROW LEVEL SECURITY;ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;ALTER TABLE site_settings ENABLE ROW LEVEL SECURITY;
